import { execFileSync } from 'node:child_process'
import { readFileSync, realpathSync } from 'node:fs'
import { join } from 'node:path'
import { checkCaliperShape, flattenProps } from './caliper-input.ts'
import {
  expectationFailure,
  expectationProblems,
  factDifferences,
  factFailures,
  listFixtures,
  PROP,
  rowKey,
  rowKeysOf,
